import React, { useState } from "react";
import { Link } from "react-router-dom";
import "../components/cliente.css";

export default function Registro() {
  const [nombre, setNombre] = useState("");
  const [correo, setCorreo] = useState("");
  const [password, setPassword] = useState("");

  const manejarRegistro = () => {
    alert(`Registrando usuario:\nNombre: ${nombre}\nCorreo: ${correo}`);
  };

  return (
    <>
      <header className="header">
        <nav>
          <div className="logo">
            <Link to="/">
              <img src="/imagenes/Logo_GO.jpeg" alt="Logo de Gurama" />
            </Link>
          </div>

          <ul>
            <li><Link to="/">Iniciar sesión</Link></li>
          </ul>
        </nav>
      </header>

      <main>
        <form className="form-registro">
          <h2 className="subtitulo">Crear cuenta</h2>

          <label htmlFor="nombre">Nombre</label>
          <input
            type="text"
            id="nombre"
            value={nombre}
            onChange={(e) => setNombre(e.target.value)}
            placeholder="Ingresa tu nombre"
          />

          <label htmlFor="correo">Correo electrónico</label>
          <input
            type="email"
            id="correo"
            value={correo}
            onChange={(e) => setCorreo(e.target.value)}
            placeholder="Ingresa tu correo"
          />

          <label htmlFor="password">Contraseña</label>
          <input
            type="password"
            id="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="Ingresa tu contraseña"
          />

          <button type="button" onClick={manejarRegistro}>
            Registrarse
          </button>
        </form>
      </main>
    </>
  );
}
